{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 instance does not have detailed monitoring enabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "LOW",
      "explanation": "The EC2 instance is not configured with detailed monitoring, which may limit visibility into its performance and security."
    },
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 instance should not have public IP address",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance may be exposed to the public internet if associated with a public subnet or has a public IP address assigned, potentially increasing the attack surface."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami           = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  availability_zone = \"us-east-2a\"\n  key_name      = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id = aws_subnet.levelupvpc-public-1.id\n  monitoring = true\n}",
  "fix_summary": "Enabled detailed monitoring for the EC2 instance. Note that the instance's potential public exposure remains as it depends on the subnet configuration not shown in this snippet."
}
